//! Golden fixture harness for deterministic POC behavior.
//!
//! The corpus under `tests/fixtures` is generated by
//! `tools/oracle/generate.py`; these tests prove the checked-in fixtures
//! match their manifest goldens, carry complete coverage, contain no
//! runtime-secret markers, and stay internally consistent with the wire and
//! mapping rules they freeze for the future Rust implementations.

#![expect(
    clippy::expect_used,
    reason = "the golden harness asserts over checked-in fixture data"
)]

mod case_tests;
mod checks;
mod loader;

use std::fs;
use std::path::{Path, PathBuf};

use loader::{Corpus, FamilyFile, GoldenError, SCHEMA, SCHEMA_VERSION, sha256_hex};

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
}

fn load() -> Corpus {
    loader::load_corpus(&fixtures_dir()).expect("checked-in fixture corpus must verify")
}

fn family<'a>(corpus: &'a Corpus, name: &str) -> &'a FamilyFile {
    corpus
        .families
        .get(name)
        .expect("manifest-listed family present")
}

#[test]
fn manifest_declares_supported_schema_and_version() {
    let corpus = load();

    assert_eq!(corpus.manifest.schema, SCHEMA);
    assert_eq!(corpus.manifest.version, SCHEMA_VERSION);
    assert_eq!(corpus.manifest.files.len(), 11);
}

#[test]
fn fixture_files_match_declared_sha256() {
    let corpus = load();
    let directory = fixtures_dir();

    for entry in &corpus.manifest.files {
        let bytes = fs::read(directory.join(&entry.path)).expect("fixture file readable");
        assert_eq!(sha256_hex(&bytes), entry.sha256, "fixture {}", entry.path);
    }
}

#[test]
fn hash_mismatch_is_a_typed_error() {
    let directory = fixtures_dir();
    let mut manifest = load().manifest;
    manifest.files[0].sha256 = "0".repeat(64);

    let error = loader::verify_fixture_dir(&directory, &manifest)
        .expect_err("a drifted fixture must not verify");

    assert!(
        matches!(error, GoldenError::HashMismatch { .. }),
        "{error:?}"
    );
}

#[test]
fn unsupported_schema_and_version_are_typed_errors() {
    let version_error = loader::parse_manifest(
        br#"{"schema": "iptv-poc-golden", "version": 99, "required_coverage": [], "forbidden_markers_sha256": "", "files": []}"#,
    )
    .expect_err("an unknown manifest version must be rejected");
    assert!(
        matches!(version_error, GoldenError::UnsupportedVersion { found: 99 }),
        "{version_error:?}"
    );

    let schema_error = loader::parse_manifest(
        br#"{"schema": "other", "version": 1, "required_coverage": [], "forbidden_markers_sha256": "", "files": []}"#,
    )
    .expect_err("an unknown manifest schema must be rejected");
    assert!(
        matches!(schema_error, GoldenError::UnsupportedSchema { .. }),
        "{schema_error:?}"
    );
}

#[test]
fn malformed_manifest_json_is_a_typed_error() {
    let error = loader::parse_manifest(b"{not json")
        .expect_err("malformed manifest bytes must be rejected");

    assert!(
        matches!(error, GoldenError::MalformedJson { .. }),
        "{error:?}"
    );
}

#[test]
fn malformed_and_mismatched_families_are_typed_errors() {
    let malformed = loader::parse_family("x.json", b"[[", "x")
        .expect_err("malformed family bytes must be rejected");
    assert!(
        matches!(malformed, GoldenError::MalformedJson { .. }),
        "{malformed:?}"
    );

    let mismatched = loader::parse_family("x.json", br#"{"family": "other", "cases": []}"#, "x")
        .expect_err("a family name mismatch must be rejected");
    assert!(
        matches!(mismatched, GoldenError::FamilyMismatch { .. }),
        "{mismatched:?}"
    );
}

#[test]
fn coverage_and_markers_match_the_generator_contract() {
    let corpus = load();

    let mut required: Vec<&str> = checks::REQUIRED_COVERAGE.to_vec();
    let mut declared: Vec<&str> = corpus
        .manifest
        .required_coverage
        .iter()
        .map(String::as_str)
        .collect();
    required.sort_unstable();
    declared.sort_unstable();
    assert_eq!(required, declared);

    let mut markers: Vec<&str> = checks::FORBIDDEN_MARKERS.to_vec();
    markers.sort_unstable();
    let markers_digest = sha256_hex(markers.join("\n").as_bytes());
    assert_eq!(markers_digest, corpus.manifest.forbidden_markers_sha256);

    for tag in checks::REQUIRED_COVERAGE {
        assert!(
            corpus
                .families
                .values()
                .flat_map(|family| family.cases.iter())
                .any(|case| case.covers.iter().any(|cover| cover == tag)),
            "required coverage tag {tag} has no fixture case"
        );
    }
    for entry in &corpus.manifest.files {
        let mut from_cases: Vec<&str> = family(&corpus, &entry.path)
            .cases
            .iter()
            .flat_map(|case| case.covers.iter())
            .map(String::as_str)
            .collect();
        from_cases.sort_unstable();
        from_cases.dedup();
        let mut declared: Vec<&str> = entry.covers.iter().map(String::as_str).collect();
        declared.sort_unstable();
        declared.dedup();
        assert_eq!(
            from_cases, declared,
            "manifest covers drift for {}",
            entry.path
        );
    }
}

#[test]
fn fixtures_contain_no_forbidden_markers() {
    let directory = fixtures_dir();

    for entry in fs::read_dir(&directory).expect("fixture directory readable") {
        let path = entry.expect("directory entry readable").path();
        if path
            .extension()
            .is_some_and(|extension| extension == "json")
        {
            let bytes = fs::read(&path).expect("fixture file readable");
            let name = path.file_name().map_or_else(
                || path.display().to_string(),
                |n| n.to_string_lossy().into_owned(),
            );
            loader::scan_forbidden(&name, &bytes).expect("fixtures carry no secret markers");
        }
    }
}
